async function asyncReduce(items, fn, init) {
  let acc = init;
  for (const item of items) {
    acc = await fn(acc, item);
  }
  return acc;
}
asyncReduce([1, 2, 3], async (acc, item) => acc + item, 0)
  .then(r => console.log(r));
